def title_for(col, slug):
    if slug in col["titles"]:
        return col["titles"][slug]
    if col["slug"] == "birth-flowers":
        month, flower = slug.split("-", 1)
        return f"{month.title()} · {flower.replace('-', ' ').title()}"
    return slug.replace("-", " ").title()
